-- CountriesGuessor: база названий для серверной проверки ходов (5663 записей).
-- Запустите ПОСЛЕ 1_schema.sql. Скрипт можно запускать повторно.
truncate table public.cg_entities;
insert into public.cg_entities(id,ukey,name,kind,first,firsts,cands)
select (row_number() over ())::int,
       split_part(l,'|',1), split_part(l,'|',2), split_part(l,'|',3),
       split_part(l,'|',4), split_part(l,'|',5), split_part(l,'|',6)
from regexp_split_to_table($cgdata$
